// Get incoming form data
const body = $input.item.json.body;
// Access the nested answers object
const answers = body.answers;

// Point mapping
const points = { 'a': 3, 'b': 2, 'c': 1 };
let totalScore = 0;

// Calculate score for all 12 questions from the 'answers' object
// Note: The incoming answers are lowercase 'a', 'b', 'c'
totalScore += points[answers.q1.toLowerCase()] || 0;
totalScore += points[answers.q2.toLowerCase()] || 0;
totalScore += points[answers.q3.toLowerCase()] || 0;
totalScore += points[answers.q4.toLowerCase()] || 0;
totalScore += points[answers.q5.toLowerCase()] || 0;
totalScore += points[answers.q6.toLowerCase()] || 0;
totalScore += points[answers.q7.toLowerCase()] || 0;
totalScore += points[answers.q8.toLowerCase()] || 0;
totalScore += points[answers.q9.toLowerCase()] || 0;
totalScore += points[answers.q10.toLowerCase()] || 0;
totalScore += points[answers.q11.toLowerCase()] || 0;
totalScore += points[answers.q12.toLowerCase()] || 0;

// Calculate score percentage
const scorePercentage = Math.round((totalScore / 36) * 100);

// Format answers for AI context from the 'answers' object
const formattedAnswers = `
Q1: ${answers.q1} | Q2: ${answers.q2} | Q3: ${answers.q3}
Q4: ${answers.q4} | Q5: ${answers.q5} | Q6: ${answers.q6}
Q7: ${answers.q7} | Q8: ${answers.q8} | Q9: ${answers.q9}
Q10: ${answers.q10} | Q11: ${answers.q11} | Q12: ${answers.q12}
`;

// Prepare output for the next nodes
return {
  json: {
    name: body.name,
    email: body.email,
    totalScore: totalScore,
    scorePercentage: scorePercentage,
    formattedAnswers: formattedAnswers
  }
};

